 int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(4),0,dp(7));t.setLineSpacing(dp(2),1f);return t;}void space(int n){View v=new View(this);body.addView(v,new LinearLayout.LayoutParams(1,dp(n)));}
 LinearLayout section(String title,String description){LinearLayout l=ui.card(body,title,description);l.setTag(title.startsWith("04")||title.startsWith("05")?"tasks":"project");return l;}
 void showPage(int tab){page=tab==2?2:0;ui.select(page);for(int i=0;i<body.getChildCount();i++){View v=body.getChildAt(i);Object tag=v.getTag();if(tag!=null)v.setVisibility(tag.equals(page==2?"tasks":"project")?View.VISIBLE:View.GONE);}}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);showPage(i.getIntExtra("studio_tab",0));}
 EditText entry(LinearLayout parent,String title,String hint,final String pref){parent.addView(text(title,14,ink));EditText e=new EditText(this);e.setTextSize(16);e.setTextColor(ink);e.setHintTextColor(muted);e.setSingleLine(true);e.setHint(hint);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});e.setText(getSharedPreferences("local",0).getString(pref,""));parent.addView(e,new LinearLayout.LayoutParams(-1,-2));ui.field(e);e.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){getSharedPreferences("local",0).edit().putString(pref,s.toString()).apply();}public void afterTextChanged(android.text.Editable e){}});return e;}
 Button button(LinearLayout parent,String label,boolean primary,View.OnClickListener click){return ui.button(parent,label,primary,click);}
 public void changed(){if(source==null)return;ui.select(page);if(localSummary!=null)try{JSONObject local=new JSONObject(new String(FilesEx.read(new FileInputStream(new File(jobs.root,"local-assistant.json")),1048576),"UTF-8"));localSummary.setText("最近诊断（输入或日志变化后请重新运行）\n"+LocalAssistant.render(local));}catch(Exception ignored){}if(logSummary!=null)try{JSONObject meta=new JSONObject(new String(FilesEx.read(new FileInputStream(new File(jobs.root,"game-log-meta.json")),65536),"UTF-8"));logSummary.setText("已导入："+meta.optString("name")+"\n日志文本："+meta.optInt("characters")+" 字符 · 等待AI分析");}catch(Exception ignored){}if(structure!=null)try{JSONObject analysis=new JSONObject(new String(FilesEx.read(new FileInputStream(new File(jobs.root,"project-analysis.json")),524288),"UTF-8"));structure.setText("最近分析（新导入后请重新分析）\n引擎："+analysis.optString("engine")+" · 条目："+analysis.optInt("entries")+"\n文本候选："+analysis.getJSONArray("text_candidates").length()+" · 完整反编译尚未接入");}catch(Exception ignored){}source.setText("游戏："+jobs.apkName);module.setText("模块："+jobs.moduleName);key.setText(jobs.keyReady?"已验证签名身份 · 仅保存在本机":"尚未导入签名文件");status.setText(jobs.status+(jobs.progress.length()>0?"  "+jobs.progress:""));String d="";if(jobs.plan!=null)try{d="匹配："+jobs.plan.profile.getString("name")+"\n";JSONArray modules=jobs.plan.profile.getJSONArray("modules");for(int i=0;i<modules.length();i++)d+="✓ "+modules.getJSONObject(i).getString("name")+"（必需）\n";d+="目标："+jobs.plan.profile.getString("output_version")+"\n识别："+(jobs.plan.matchMode.equals("exact")?"完整校验匹配":"逐文件兼容，自动处理差异");if(jobs.report.has("previous_success"))d+="\n本机有成功处理记录，已重新核验";}catch(Exception ignored){}detail.setText(d);buildWindow.setText(BuildView.render(jobs.buildTask?jobs.report:jobs.buildReport));bar.setVisibility(View.VISIBLE);boolean numeric=jobs.buildTask&&jobs.progress.contains("%");bar.setIndeterminate(jobs.busy&&!numeric);bar.setMax(100);try{bar.setProgress(numeric?Integer.parseInt(jobs.progress.substring(0,jobs.progress.indexOf("%"))):jobs.buildReport.optString("status").equals("success")?100:0);}catch(Exception ignored){}cancel.setVisibility(jobs.busy?View.VISIBLE:View.GONE);boolean idle=!jobs.busy;releaseName.setEnabled(idle);releaseVersion.setEnabled(idle);if(jobs.plan!=null)releaseVersion.setHint(jobs.plan.profile.optString("output_version"));pickApk.setEnabled(idle);pickModule.setEnabled(idle);pickKey.setEnabled(idle);check.setEnabled(idle&&jobs.file(1).isFile()&&jobs.file(2).isFile());build.setEnabled(idle&&jobs.file(1).isFile()&&jobs.file(2).isFile()&&jobs.keyReady);boolean has=jobs.output!=null&&jobs.output.isFile();install.setEnabled(idle&&has);save.setEnabled(idle&&has);diagnose.setEnabled(idle);for(Button b:new Button[]{pickApk,pickModule,pickKey,check,build,install,save,diagnose})b.setAlpha(b.isEnabled()?1f:.42f);result.setText(has?"上次成功结果："+jobs.outputLabel:"暂无成功生成的 APK");}
 void pick(int kind){if(jobs.busy)return;Intent i=new Intent("android.intent.action.OPEN_DOCUMENT");i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|64);try{startActivityForResult(i,kind);}catch(Exception e){Toast.makeText(this,"无法打开系统文件选择器",Toast.LENGTH_LONG).show();}}
 String display(Uri uri){Cursor c=null;try{c=getContentResolver().query(uri,new String[]{"_display_name"},null,null,null);if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}finally{if(c!=null)c.close();}return "已选择文件";}
 void saveAs(boolean logs){Intent i=new Intent("android.intent.action.CREATE_DOCUMENT");i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(logs?"application/zip":"application/vnd.android.package-archive");i.putExtra(Intent.EXTRA_TITLE,logs?"MDZ_诊断_"+System.currentTimeMillis()+".zip":(jobs.output==null?"MiniDayZ2_共存版.apk":jobs.output.getName()));try{startActivityForResult(i,logs?SAVE_LOG:SAVE_APK);}catch(Exception e){Toast.makeText(this,"无法打开保存位置",Toast.LENGTH_LONG).show();}}
 protected void onActivityResult(final int request,int code,Intent data){super.onActivityResult(request,code,data);if(code!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();if(request==IMPORT_GAME_LOG){final String name=display(uri);jobs.begin("读取游戏日志",new Jobs.Work(){public void run(Jobs j)throws Exception{GameLogs.importLog(j,uri,name);}});return;}if(request>=1&&request<=3){try{getContentResolver().getClass().getMethod("takePersistableUriPermission",Uri.class,int.class).invoke(getContentResolver(),uri,1);}catch(Exception ignored){}final String name=display(uri);jobs.begin("导入文件",new Jobs.Work(){public void run(Jobs j)throws Exception{j.importFile(uri,request,name);}});}else if(request==SAVE_APK||request==SAVE_LOG)jobs.exportTask(new Jobs.Work(){public void run(Jobs j)throws Exception{j.export(uri,request==SAVE_LOG);}});}
 void install(){try{if(Build.VERSION.SDK_INT>=26){boolean allowed=(Boolean)getPackageManager().getClass().getMethod("canRequestPackageInstalls").invoke(getPackageManager());if(!allowed){startActivity(new Intent("android.settings.MANAGE_UNKNOWN_APP_SOURCES",Uri.parse("package:"+getPackageName())));Toast.makeText(this,"允许此来源后，返回点击安装",Toast.LENGTH_LONG).show();return;}}Uri uri=Uri.parse("content://cn.minidayz.patcher.files/latest.apk");Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(uri,"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("P版构建结果",uri));startActivity(i);}catch(Exception e){Toast.makeText(this,"无法打开安装界面，可先另存 APK 再安装",Toast.LENGTH_LONG).show();}}
